 "content": "def transform(grid):
    """Fill the cells between aligned marker cells with color 3."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next((v for row in grid for v in row if v not in (8,)), None)
    # ARC instances may use different background/marker colors; identify the
    # non-background color as the least frequent color, with background most frequent.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    marker = min(counts, key=counts.get)
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
